UPDATE public.learning_paths set content=jsonb_set(jsonb_set(jsonb_set(jsonb_set(content,'{chapters,0,lessons}','[{"id": "garden-1", "title": "Les sosies du jardin", "title_en": "Garden look-alikes", "intro": "Ils se ressemblent à s''y méprendre. Un seul détail fait la différence.", "intro_en": "They look almost identical. One detail gives them away.", "questions": [{"type": "duel", "prompt": "Laquelle est la Mésange noire ?", "prompt_en": "Which one is the coal tit?", "options": ["Celle-ci", "Celle-là"], "options_en": ["This one", "That one"], "correct": 1, "explanation": "La Mésange noire n''a pas de ventre jaune et porte une tache blanche sur la nuque. La charbonnière, elle, a une cravate noire sur un ventre jaune vif.", "explanation_en": "The coal tit has no yellow belly and shows a white patch on the nape. The great tit wears a black tie on a bright yellow belly.", "images": ["https://inaturalist-open-data.s3.amazonaws.com/photos/339051675/medium.jpg", "https://inaturalist-open-data.s3.amazonaws.com/photos/123425023/medium.jpeg"], "credit": "Parus major : (c) Sylvain Montagner, some rights reserved (CC BY) · Periparus ater : (c) xulescu_g, some rights reserved (CC BY-SA) · iNaturalist"}, {"type": "duel", "prompt": "Lequel est le Moineau friquet ?", "prompt_en": "Which one is the Eurasian tree sparrow?", "options": ["Celui-ci", "Celui-là"], "options_en": ["This one", "That one"], "correct": 1, "explanation": "Calotte brun chocolat et tache noire sur la joue blanche : c''est le friquet. Et contrairement au domestique, mâle et femelle sont identiques.", "explanation_en": "Chocolate crown and a black spot on a white cheek: that''s the tree sparrow. Unlike the house sparrow, males and females look the same.", "images": ["https://inaturalist-open-data.s3.amazonaws.com/photos/136543105/medium.jpeg", "https://inaturalist-open-data.s3.amazonaws.com/photos/608112754/medium.jpg"], "credit": "Passer domesticus : (c) Esteban Poveda, some rights reserved (CC BY) · Passer montanus : (c) Radu Teodoreanu, some rights reserved (CC BY) · iNaturalist"}, {"type": "duel", "prompt": "Lequel ne se pose presque jamais ?", "prompt_en": "Which one almost never lands?", "options": ["Celui-ci", "Celui-là"], "options_en": ["This one", "That one"], "correct": 1, "explanation": "Le Martinet noir n''est même pas une hirondelle. Il mange, boit et dort en vol, et peut rester jusqu''à 10 mois dans les airs sans se poser.", "explanation_en": "The common swift isn''t even a swallow. It eats, drinks and sleeps on the wing, and can stay airborne for up to 10 months.", "images": ["https://inaturalist-open-data.s3.amazonaws.com/photos/8209375/medium.jpeg", "https://inaturalist-open-data.s3.amazonaws.com/photos/382277341/medium.jpeg"], "credit": "Hirundo rustica : no rights reserved · Apus apus : no rights reserved · iNaturalist"}, {"type": "boolean", "prompt": "La femelle du Merle noir est noire, elle aussi.", "prompt_en": "The female common blackbird is black too.", "options": ["Vrai", "Faux"], "options_en": ["True", "False"], "correct": 1, "explanation": "Faux ! La femelle est brun chocolat, souvent avec une gorge tachetée. Beaucoup la prennent pour une grive.", "explanation_en": "False! The female is chocolate brown, often with a speckled throat. Many people mistake her for a thrush."}, {"type": "mcq", "prompt": "Combien de temps un Martinet noir peut-il voler sans jamais se poser ?", "prompt_en": "How long can a common swift fly without ever landing?", "options": ["10 jours", "2 mois", "10 mois"], "options_en": ["10 days", "2 months", "10 months"], "correct": 2, "explanation": "Des balises posées sur des martinets suédois ont montré jusqu''à 10 mois de vol continu, entre deux saisons de nidification.", "explanation_en": "Trackers on Swedish swifts recorded up to 10 months of continuous flight between two breeding seasons."}]}, {"id": "garden-2", "title": "Mythes et faux amis", "title_en": "Myths and impostors", "intro": "Ce que tout le monde croit savoir… et qui est faux.", "intro_en": "What everyone thinks they know… and gets wrong.", "questions": [{"type": "boolean", "prompt": "Une soucoupe de lait aide les hérissons à passer l''hiver.", "prompt_en": "A saucer of milk helps hedgehogs through winter.", "options": ["Vrai", "Faux"], "options_en": ["True", "False"], "correct": 1, "explanation": "Faux, et c''est dangereux : les hérissons ne digèrent pas le lactose. Le lait leur donne des diarrhées parfois mortelles. Une coupelle d''eau suffit.", "explanation_en": "False, and dangerous: hedgehogs can''t digest lactose. Milk gives them sometimes fatal diarrhoea. A dish of water is enough."}, {"type": "intruder", "prompt": "Lequel n''est PAS un rongeur ?", "prompt_en": "Which one is NOT a rodent?", "options": ["Écureuil roux", "Lièvre d''Europe", "Mulot sylvestre", "Rat surmulot"], "options_en": ["Red squirrel", "European hare", "Wood mouse", "Brown rat"], "correct": 1, "explanation": "Le lièvre est un lagomorphe, comme le lapin. Le signe qui ne trompe pas : une deuxième petite paire d''incisives cachée derrière les premières.", "explanation_en": "The hare is a lagomorph, like the rabbit. The giveaway: a second tiny pair of incisors hidden behind the front ones.", "images": ["https://inaturalist-open-data.s3.amazonaws.com/photos/9638767/medium.jpeg", "https://inaturalist-open-data.s3.amazonaws.com/photos/15438896/medium.png", "https://inaturalist-open-data.s3.amazonaws.com/photos/626298711/medium.jpg", "https://inaturalist-open-data.s3.amazonaws.com/photos/227790437/medium.jpeg"], "credit": "Sciurus vulgaris : (c) Natalya Ivanova, some rights reserved (CC BY) · Lepus europaeus : (c) Grete Pasch, some rights reserved (CC BY) · Apodemus sylvaticus : (c) franktl, some rights reserved (CC BY) · Rattus norvegicus : (c) Juan Carlos Caicedo Hernández, some rights reserved (CC BY) · iNaturalist"}, {"type": "intruder", "prompt": "Lequel n''est PAS un serpent ?", "prompt_en": "Which one is NOT a snake?", "options": ["Orvet fragile", "Couleuvre helvétique", "Vipère aspic", "Couleuvre verte et jaune"], "options_en": ["Slow worm", "Barred grass snake", "Asp viper", "Green whip snake"], "correct": 0, "explanation": "L''orvet est un lézard sans pattes ! Il cligne des yeux (les serpents n''ont pas de paupières mobiles) et peut perdre sa queue pour échapper à un prédateur.", "explanation_en": "The slow worm is a legless lizard! It blinks (snakes have no movable eyelids) and can shed its tail to escape a predator.", "images": ["https://inaturalist-open-data.s3.amazonaws.com/photos/463596860/medium.jpg", "https://inaturalist-open-data.s3.amazonaws.com/photos/319158753/medium.jpg", "https://inaturalist-open-data.s3.amazonaws.com/photos/363809821/medium.jpeg", "https://inaturalist-open-data.s3.amazonaws.com/photos/86005471/medium.jpeg"], "credit": "Anguis fragilis : (c) C. Oppermann, some rights reserved (CC BY-SA) · Natrix helvetica : (c) Sylvain Montagner, some rights reserved (CC BY) · Vipera aspis : no rights reserved · Hierophis viridiflavus : (c) Crap Fou, some rights reserved (CC BY) · iNaturalist"}, {"type": "boolean", "prompt": "La Taupe d''Europe est complètement aveugle.", "prompt_en": "The European mole is completely blind.", "options": ["Vrai", "Faux"], "options_en": ["True", "False"], "correct": 1, "explanation": "Faux. Ses yeux minuscules, cachés dans la fourrure, distinguent la lumière de l''obscurité. Elle « voit » surtout avec son museau ultra-sensible.", "explanation_en": "False. Its tiny eyes, hidden in the fur, tell light from dark. It mostly ''sees'' with its ultra-sensitive snout."}, {"type": "mcq", "prompt": "Combien de chenilles un couple de mésanges charbonnières peut-il apporter à une seule nichée ?", "prompt_en": "How many caterpillars can a pair of great tits bring to a single brood?", "options": ["Environ 500", "Environ 2 000", "Jusqu''à 10 000"], "options_en": ["About 500", "About 2,000", "Up to 10,000"], "correct": 2, "explanation": "Jusqu''à 10 000 chenilles en trois semaines : un nichoir à mésanges est l''un des meilleurs insecticides naturels du jardin.", "explanation_en": "Up to 10,000 caterpillars in three weeks: a tit nest box is one of the best natural pest controls in a garden."}]}]'::jsonb),'{chapters,1,lessons}','[{"id": "garden-3", "title": "Blind test du crépuscule", "title_en": "Twilight blind test", "intro": "Ferme les yeux, monte le son. Qui se cache dans le noir ?", "intro_en": "Close your eyes, turn up the sound. Who''s hiding in the dark?", "questions": [{"type": "audio", "prompt": "Qui chante dans ce bois ?", "prompt_en": "Who is calling in these woods?", "options": ["Chouette hulotte", "Effraie des clochers", "Renard roux"], "options_en": ["Tawny owl", "Barn owl", "Red fox"], "correct": 0, "explanation": "Le célèbre « hou-hou-houuu » est le chant du mâle de Chouette hulotte. La femelle lui répond par un « kiwitt » aigu.", "explanation_en": "The famous ''hoo-hoo-hoooo'' is the male tawny owl. The female answers with a sharp ''kewick''.", "audio": "https://static.inaturalist.org/sounds/449933.mp3?1653425643", "credit": "(c) Patrick Hacker, some rights reserved (CC BY) · iNaturalist"}, {"type": "audio", "prompt": "Ce cri strident vient de…", "prompt_en": "This shrill screech comes from…", "options": ["Chouette hulotte", "Effraie des clochers", "Hibou moyen-duc"], "options_en": ["Tawny owl", "Barn owl", "Long-eared owl"], "correct": 1, "explanation": "L''Effraie ne hulule jamais : elle chuinte et pousse des cris rauques. Ce son dans un clocher a nourri bien des légendes de fantômes.", "explanation_en": "Barn owls never hoot: they hiss and screech. That sound in a church tower fuelled many ghost stories.", "audio": "https://static.inaturalist.org/sounds/1112782.m4a?1719607418", "credit": "(c) Fabrizio Benedetti, some rights reserved (CC BY) · iNaturalist"}, {"type": "audio", "prompt": "Qui chante, même en plein hiver ?", "prompt_en": "Who sings, even in the depths of winter?", "options": ["Rouge-gorge familier", "Merle noir", "Pinson des arbres"], "options_en": ["European robin", "Common blackbird", "Common chaffinch"], "correct": 0, "explanation": "Le Rouge-gorge chante presque toute l''année pour défendre son territoire, parfois la nuit sous un lampadaire.", "explanation_en": "The robin sings nearly all year to defend its territory, sometimes at night under a streetlight.", "audio": "https://static.inaturalist.org/sounds/375771.m4a?1647861271", "credit": "(c) Tatiana Efremova, some rights reserved (CC BY) · iNaturalist"}, {"type": "boolean", "prompt": "Une chouette peut tourner la tête à 360°.", "prompt_en": "An owl can turn its head 360°.", "options": ["Vrai", "Faux"], "options_en": ["True", "False"], "correct": 1, "explanation": "Faux : environ 270°. C''est déjà énorme, grâce à 14 vertèbres cervicales (deux fois plus que nous) et des vaisseaux sanguins protégés.", "explanation_en": "False: about 270°. That''s already huge, thanks to 14 neck vertebrae (twice as many as us) and protected blood vessels."}, {"type": "mcq", "prompt": "Pourquoi le vol de l''Effraie est-il presque silencieux ?", "prompt_en": "Why is the barn owl''s flight almost silent?", "options": ["Ses plumes sont frangées comme un peigne", "Elle ne bat jamais des ailes", "Elle vole très lentement"], "options_en": ["Its feathers have comb-like fringes", "It never flaps its wings", "It flies very slowly"], "correct": 0, "explanation": "Le bord de ses plumes est dentelé comme un peigne : il casse les turbulences de l''air. Les ingénieurs s''en inspirent pour des pales d''éoliennes plus silencieuses.", "explanation_en": "Its feather edges are serrated like a comb, breaking up air turbulence. Engineers copy it to make quieter wind turbine blades."}]}, {"id": "garden-4", "special": true, "title": "Défi : maître du jardin", "title_en": "Challenge: garden master", "intro": "Cinq questions, aucun indice. Prouve que tu connais ton jardin.", "intro_en": "Five questions, no hints. Prove you know your garden.", "questions": [{"type": "duel", "prompt": "Lequel pèse le plus lourd ?", "prompt_en": "Which one is heavier?", "options": ["Celui-ci", "Celui-là"], "options_en": ["This one", "That one"], "correct": 0, "explanation": "Un hérisson adulte pèse 800 g à 1,2 kg avant l''hiver, soit trois à quatre fois un écureuil roux (250 à 340 g).", "explanation_en": "An adult hedgehog weighs 800 g to 1.2 kg before winter, three to four times a red squirrel (250–340 g).", "images": ["https://inaturalist-open-data.s3.amazonaws.com/photos/205239510/medium.jpeg", "https://inaturalist-open-data.s3.amazonaws.com/photos/9638767/medium.jpeg"], "credit": "Erinaceus europaeus : (c) Justin Cormack, some rights reserved (CC BY) · Sciurus vulgaris : (c) Natalya Ivanova, some rights reserved (CC BY) · iNaturalist"}, {"type": "audio", "prompt": "À qui appartient cette mélodie ?", "prompt_en": "Whose melody is this?", "options": ["Étourneau sansonnet", "Merle noir", "Grive musicienne"], "options_en": ["Common starling", "Common blackbird", "Song thrush"], "correct": 1, "explanation": "Le Merle flûte des phrases lentes et variées, souvent depuis une antenne au crépuscule. La grive, elle, répète chaque motif deux ou trois fois.", "explanation_en": "The blackbird fluting slow, varied phrases, often from a TV aerial at dusk. The song thrush repeats each phrase two or three times.", "audio": "https://static.inaturalist.org/sounds/560391.m4a?1667845906", "credit": "(c) Richard Littauer, CC BY · iNaturalist"}, {"type": "boolean", "prompt": "L''Étourneau sansonnet peut imiter une sonnerie de téléphone.", "prompt_en": "A common starling can mimic a phone ringtone.", "options": ["Vrai", "Faux"], "options_en": ["True", "False"], "correct": 0, "explanation": "Vrai ! C''est un imitateur hors pair : alarmes de voiture, sonneries, autres oiseaux… Mozart en avait même un qui sifflait sa musique.", "explanation_en": "True! It''s a master mimic: car alarms, ringtones, other birds… Mozart even kept one that whistled his music."}, {"type": "mcq", "prompt": "En hiver, qui chante chez le Rouge-gorge ?", "prompt_en": "In winter, which robins sing?", "options": ["Seulement le mâle", "Le mâle et la femelle", "Aucun des deux"], "options_en": ["Only the male", "Both male and female", "Neither"], "correct": 1, "explanation": "Fait rare chez les oiseaux : la femelle Rouge-gorge défend son propre territoire d''hiver, et elle chante pour ça.", "explanation_en": "Rare among birds: the female robin holds her own winter territory, and she sings to defend it."}, {"type": "duel", "prompt": "Lequel est le Merle noir ?", "prompt_en": "Which one is the common blackbird?", "options": ["Celui-ci", "Celui-là"], "options_en": ["This one", "That one"], "correct": 1, "explanation": "Le Merle mâle est d''un noir uni avec un bec et un cercle oculaire jaune orangé. L''Étourneau est moucheté et irisé.", "explanation_en": "The male blackbird is plain black with an orange-yellow bill and eye-ring. The starling is speckled and iridescent.", "images": ["https://inaturalist-open-data.s3.amazonaws.com/photos/9368838/medium.jpg", "https://inaturalist-open-data.s3.amazonaws.com/photos/31623386/medium.jpeg"], "credit": "Sturnus vulgaris : (c) Paolo Zucca, some rights reserved (CC BY) · Turdus merula : (c) Alexis Tinker-Tsavalas, some rights reserved (CC BY) · iNaturalist"}]}]'::jsonb),'{chapters,0,title}','"Les pièges du jardin"'),'{chapters,0,title_en}','"Garden traps"') where id='73ecaa10-8409-423a-9c99-3935a55e9001';